#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Simple online predictor wrapper for rna_predict_pipeline_v3_1.py

- Input: textarea CSV content (GeneName,Label,Length,Sequence)
- Writes to INPUT/<timestamp>_<rand>.csv
- Runs predictor in tf env's python (recommended: use same interpreter that runs this app)
- Shows summary text on page
- Provides download link for predictions.csv

Security notes:
- This app is intended for trusted / internal network use.
- It writes files under INPUT/ and OUT/ only.
"""

import os
import secrets
import subprocess
from datetime import datetime
from pathlib import Path

from flask import Flask, render_template, request, send_from_directory, url_for, flash, redirect

APP_DIR = Path(__file__).resolve().parent
INPUT_DIR = APP_DIR / "INPUT"
OUT_DIR = APP_DIR / "OUT"
INPUT_DIR.mkdir(exist_ok=True)
OUT_DIR.mkdir(exist_ok=True)

EXAMPLES_DIR = APP_DIR / "examples"

def list_examples():
    if not EXAMPLES_DIR.exists():
        return []
    # 只展示 csv，按文件名排序
    return sorted([p.name for p in EXAMPLES_DIR.glob("*.csv")])

def load_example_text(name: str) -> str:
    # 简单防注入：只允许 basename
    name = os.path.basename(name)
    p = EXAMPLES_DIR / name
    if not p.exists():
        return ""
    return p.read_text(encoding="utf-8", errors="ignore")

# Adjust these paths for your deployment directory (/home/hgq/BioData/hgq/ncRNA)
PREDICT_SCRIPT = APP_DIR / "rna_predict_pipeline_v3_1.py"
STEP1_CREATE_NV = APP_DIR / "step1_create_NV.py"

# Default model paths (you can change via environment variables)
MLP_MODEL = os.environ.get("MLP_MODEL", str(APP_DIR / "best_models" / "ENA_binary_classification_model.h5"))
MLP_LE    = os.environ.get("MLP_LE",    str(APP_DIR / "best_models" / "ENA_label_encoder.pkl"))
XGB_MODEL = os.environ.get("XGB_MODEL", str(APP_DIR / "best_models_seed42_set10" / "rnacentral_best_xgb.pkl"))
XGB_LE    = os.environ.get("XGB_LE",    str(APP_DIR / "best_models_seed42_set10" / "rnacentral_label_encoder.pkl"))

# Use the python executable that is running this Flask app (should be tf env)
PYTHON = os.environ.get("PYTHON_BIN", os.sys.executable)

MAX_CHARS = int(os.environ.get("MAX_INPUT_CHARS", "2000000"))  # 2MB of text

app = Flask(__name__)
app.secret_key = os.environ.get("FLASK_SECRET_KEY", "dev-secret-change-me")


