@app.get("/")
def index():
    examples = list_examples()
    return render_template("index.html", default_text=DEFAULT_TEXT, summary=None, pred_link=None, examples=examples)

@app.get("/example/<path:name>")
def example(name):
    examples = list_examples()
    text = load_example_text(name)
    if not text.strip():
        flash(f"Example not found: {name}")
        return redirect(url_for("index"))
    return render_template("index.html", default_text=text, summary=None, pred_link=None, examples=examples)

@app.post("/predict")
def predict():
    examples = list_examples()
    text = request.form.get("csv_text", "")
    if not text.strip():
        flash("Empty input.")
        return redirect(url_for("index"))
    if len(text) > MAX_CHARS:
        flash(f"Input too large (>{MAX_CHARS} chars).")
        return redirect(url_for("index"))

    ts = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    token = secrets.token_hex(4)
    in_name = f"{ts}_{token}.csv"
    out_prefix = f"{ts}_{token}"

    in_path = INPUT_DIR / in_name
    out_prefix_path = OUT_DIR / out_prefix

    in_path.write_text(text, encoding="utf-8")

    cmd = [
        PYTHON, str(PREDICT_SCRIPT),
        "--input", str(in_path),
        "--out_prefix", str(out_prefix_path),
        "--step1_create_nv", str(STEP1_CREATE_NV),
        "--mlp_model", str(MLP_MODEL),
        "--mlp_label_encoder", str(MLP_LE),
        "--xgb_model", str(XGB_MODEL),
        "--xgb_label_encoder", str(XGB_LE),
    ]

    try:
        r = subprocess.run(cmd, capture_output=True, text=True, cwd=str(APP_DIR), timeout=300)
    except subprocess.TimeoutExpired:
        flash("Prediction timed out.")
        return redirect(url_for("index"))

    # summary file
    summ_path = OUT_DIR / f"{out_prefix}.summary.txt"
    pred_path = OUT_DIR / f"{out_prefix}.predictions.csv"

    summary = ""
    if summ_path.exists():
        summary = summ_path.read_text(encoding="utf-8")
    else:
        # fallback: show stdout/stderr
        summary = (r.stdout or "") + "\n" + (r.stderr or "")

    pred_link = None
    if pred_path.exists():
        pred_link = url_for("download", filename=pred_path.name)

    return render_template("index.html", default_text=text, summary=summary, pred_link=pred_link, examples=examples)

@app.get("/download/<path:filename>")
def download(filename):
    return send_from_directory(OUT_DIR, filename, as_attachment=True)

if __name__ == "__main__":
    # Bind to 0.0.0.0 for server use; set PORT env var if needed
    port = int(os.environ.get("PORT", "8080"))
    app.run(host="0.0.0.0", port=port, debug=False)
